package io.github.ksuzukigh.rokidzoomincamera;

/**
 * Turns noisy input into clean single steps.
 *
 * On the RV101 one swipe on the temple can arrive twice: as touch events and as
 * DPAD/scroll keys generated by the system, sometimes with opposite signs, and
 * the ring wheel can send several events per click. Rules:
 *  - while a finger is on the temple (and shortly after) keys/wheel are ignored,
 *    the touch swipe alone decides;
 *  - at most one step per STEP_GAP_MS from any source.
 * Pure Java so it can be unit tested.
 */
final class InputArbiter {
    static final long STEP_GAP_MS = 280L;
    static final long TOUCH_SHADOW_MS = 350L;
    /** Zoom uses small 0.1x steps, so it accepts clicks much faster; this only
     *  merges the RIGHT+DOWN pair (and burst) that one wheel click sends. */
    static final long ZOOM_GAP_MS = 90L;

    private boolean touching;
    private long touchUpAt = Long.MIN_VALUE / 2;
    private long lastStepAt = Long.MIN_VALUE / 2;

    void touchDown(long now) {
        touching = true;
    }

    void touchUp(long now) {
        touching = false;
        touchUpAt = now;
    }

    /** A swipe finished on the temple. */
    boolean acceptSwipe(long now) {
        return acceptStep(now);
    }

    /** A DPAD / volume / scroll step (ring wheel or system-generated). */
    boolean acceptKey(long now) {
        if (touching || now - touchUpAt < TOUCH_SHADOW_MS) return false;
        return acceptStep(now);
    }

    /** A wheel / swipe key while zooming. */
    boolean acceptZoomKey(long now) {
        if (touching || now - touchUpAt < TOUCH_SHADOW_MS) return false;
        return acceptStep(now, ZOOM_GAP_MS);
    }

    private boolean acceptStep(long now) {
        return acceptStep(now, STEP_GAP_MS);
    }

    private boolean acceptStep(long now, long gap) {
        if (now - lastStepAt < gap) return false;
        lastStepAt = now;
        return true;
    }
}
